// Park the fold on `#ff-near1`: three rows sit ~1500px ABOVE the frame's box and twelve sit ~1700px
// BELOW it, both well outside the +/-1000px visibility slack. That is what makes the hidden-element
// hints fire in both directions at once, which is the only way to observe that they are sorted by
// ABSOLUTE distance rather than by signed offset. Deterministic: one absolute scroll, no timers.
window.scrollTo(0, 3 * 61 + 1500);

